-- 4. 学习资料 ----------------------------------------------------------
INSERT INTO t_learn_material (id,category_id,title,summary,file_type,file_url,content,file_size,page_count,duration_sec,tags,apply_level,visible_scope,need_audit,audit_status,audit_by,audit_time,version,upload_org_id,upload_org_path,create_by) VALUES (1,2,'《中国共产党纪律处分条例》（2023年修订）学习要点','条例3编11章158条的核心内容梳理：总则原则、四种形态、五种处分种类及影响期、六大纪律分则结构。',5,NULL,'<h2>《中国共产党纪律处分条例》（2023年修订）学习要点</h2>
<p>2023年12月8日中共中央政治局会议第三次修订，2023年12月19日中共中央发布，修订后的《条例》共3编、11章、158条，自2024年1月1日起施行。</p>
<h3>一、总则要点</h3>
<p><b>1. 指导思想与原则（第四条）</b>：党的纪律处分工作遵循下列原则：坚持党要管党、全面从严治党；党纪面前一律平等；实事求是；民主集中制；惩前毖后、治病救人。</p>
<p><b>2. 监督执纪"四种形态"（第五条）</b>：经常开展批评和自我批评，及时进行谈话提醒、批评教育、责令检查、诫勉，让"红红脸、出出汗"成为常态；党纪轻处分、组织调整成为违纪处理的大多数；党纪重处分、重大职务调整的成为少数；严重违纪涉嫌犯罪追究刑事责任的成为极少数。</p>
<p><b>3. 处分种类（第八条）</b>：对党员的纪律处分种类为警告、严重警告、撤销党内职务、留党察看、开除党籍。对严重违犯党纪、本身又不能纠正的党组织，可以予以改组或者解散（第九条）。</p>
<p><b>4. 处分影响期</b>：警告处分一年内、严重警告处分一年半内，不得在党内提拔职务或者进一步使用（第十条）；撤销党内职务处分或依规定受到的严重警告处分，二年内不得担任与原任职务相当或者更高的职务（第十一条）；留党察看最长不得超过二年，受处分期间没有表决权、选举权和被选举权，党内职务自然撤销（第十二条）；开除党籍处分五年内不得重新入党（第十三条）。</p>
<p><b>5. 运用规则</b>：第十七条规定了可以从轻或者减轻处分的六种情形（主动交代、配合审查、检举立功、挽回损失、主动上交退赔违纪所得等）；第二十条规定了应当从重或者加重处分的情形（强迫唆使他人违纪、拒不上交退赔违纪所得、受处分后又故意违纪等）。一人有两种以上违纪行为的合并处理，按最高处分加重一档（第二十四条）。</p>
<h3>二、分则结构（六大纪律）</h3>
<ul>
<li>第六章 对违反政治纪律行为的处分（第四十九条至第七十六条）</li>
<li>第七章 对违反组织纪律行为的处分（第七十七条至第九十三条）</li>
<li>第八章 对违反廉洁纪律行为的处分（第九十四条至第一百二十一条）</li>
<li>第九章 对违反群众纪律行为的处分（第一百二十二条至第一百二十九条）</li>
<li>第十章 对违反工作纪律行为的处分（第一百三十条至第一百四十九条）</li>
<li>第十一章 对违反生活纪律行为的处分（第一百五十条至第一百五十四条）</li>
</ul>
<p>资料来源：共产党员网、中国政府网发布的《中国共产党纪律处分条例》（2023年修订）全文。</p>',NULL,12,1800,'["党纪法规", "纪律处分条例", "总则"]'::jsonb,2,'{"type":"ALL"}'::jsonb,0,2,1,now(),1,1,'/1/',1) ON CONFLICT DO NOTHING;
INSERT INTO t_learn_material (id,category_id,title,summary,file_type,file_url,content,file_size,page_count,duration_sec,tags,apply_level,visible_scope,need_audit,audit_status,audit_by,audit_time,version,upload_org_id,upload_org_path,create_by) VALUES (2,2,'《中国共产党纪律处分条例》（2023年修订）全文（PDF）','2023年12月19日中共中央发布、2024年1月1日起施行的《中国共产党纪律处分条例》全文PDF（158条）。',1,'learn/jlvcfl-2023.pdf',NULL,594188,27,3600,'["党纪法规", "纪律处分条例", "全文PDF"]'::jsonb,2,'{"type":"ALL"}'::jsonb,0,2,1,now(),1,1,'/1/',1) ON CONFLICT DO NOTHING;
INSERT INTO t_learn_material (id,category_id,title,summary,file_type,file_url,content,file_size,page_count,duration_sec,tags,apply_level,visible_scope,need_audit,audit_status,audit_by,audit_time,version,upload_org_id,upload_org_path,create_by) VALUES (3,3,'中央八项规定及实施细则学习要点','2012年12月4日中央政治局审议通过的八项规定八个方面内容及实施细则30条要点。',5,NULL,'<h2>中央八项规定及实施细则学习要点</h2>
<p>2012年12月4日，中共中央政治局会议审议通过《十八届中央政治局关于改进工作作风、密切联系群众的八项规定》。</p>
<h3>一、八项规定主要内容</h3>
<ol>
<li><b>改进调查研究</b>：到基层调研要深入了解真实情况，切忌走过场、搞形式主义；要轻车简从、减少陪同、简化接待，不张贴悬挂标语横幅，不安排群众迎送，不铺设迎宾地毯，不摆放花草，不安排宴请。</li>
<li><b>精简会议活动</b>：切实改进会风，严格控制以中央名义召开的各类全国性会议和举行的重大活动，不开泛泛部署工作和提要求的会；提高会议实效，开短会、讲短话，力戒空话、套话。</li>
<li><b>精简文件简报</b>：切实改进文风，没有实质内容、可发可不发的文件、简报一律不发。</li>
<li><b>规范出访活动</b>：从外交工作大局需要出发合理安排出访活动，严格控制出访随行人员，严格按照规定乘坐交通工具。</li>
<li><b>改进警卫工作</b>：坚持有利于联系群众的原则，减少交通管制，一般情况下不得封路、不清场闭馆。</li>
<li><b>改进新闻报道</b>：根据工作需要、新闻价值、社会效果决定是否报道，进一步压缩报道的数量、字数、时长。</li>
<li><b>严格文稿发表</b>：除中央统一安排外，个人不公开出版著作、讲话单行本，不发贺信、贺电，不题词、题字。</li>
<li><b>厉行勤俭节约</b>：严格遵守廉洁从政有关规定，严格执行住房、车辆配备等有关工作和生活待遇的规定。</li>
</ol>
<h3>二、实施细则要点</h3>
<p>实施细则从改进调查研究、精简会议活动和文件简报、规范出访活动、改进新闻报道、加强督促检查五个方面作出30条具体规定。要点包括：各部门召开本系统全国性会议每年不超过1次；全国性会议人数不超过300人、时间不超过2天；会议活动现场布置要简朴，工作会议一律不摆花草、不制作背景板；严禁以任何名义发放纪念品；严禁提高会议用餐、住宿标准，严禁组织高消费娱乐、健身活动；各地区各部门每年年底对执行情况进行1次专项检查。</p>
<p>各级纪检监察机关要把监督执行八项规定及实施细则作为改进党风政风的一项经常性工作来抓。</p>',NULL,10,1500,'["中央八项规定", "作风建设"]'::jsonb,2,'{"type":"ALL"}'::jsonb,0,2,1,now(),1,1,'/1/',1) ON CONFLICT DO NOTHING;
INSERT INTO t_learn_material (id,category_id,title,summary,file_type,file_url,content,file_size,page_count,duration_sec,tags,apply_level,visible_scope,need_audit,audit_status,audit_by,audit_time,version,upload_org_id,upload_org_path,create_by) VALUES (4,3,'违反中央八项规定精神问题的主要类型与定性依据','违规收送礼品礼金、违规吃喝、公款旅游、大操大办婚丧喜庆等问题的条例定性条款对照。',5,NULL,'<h2>违反中央八项规定精神问题的主要类型与定性依据</h2>
<p>中央八项规定精神是长期有效的铁规矩、硬杠杠。《中国共产党纪律处分条例》（2023年修订）第七条明确，重点查处违反中央八项规定精神的问题。结合条例分则，常见违纪类型及定性条款如下：</p>
<h3>1. 违规收送礼品礼金</h3>
<p>收受可能影响公正执行公务的礼品、礼金、消费卡（券）和有价证券、股权、其他金融产品等财物，适用条例第九十七条；向从事公务的人员及其亲属赠送明显超出正常礼尚往来的财物，适用第九十八条；以讲课费、课题费、咨询费等名义变相送礼的，依照第九十八条处理。</p>
<h3>2. 违规吃喝与宴请</h3>
<p>接受、提供可能影响公正执行公务的宴请或者旅游、健身、娱乐等活动安排，适用第一百零一条；违反有关规定组织、参加用公款支付的宴请、娱乐、健身活动，适用第一百一十三条；违反接待管理规定，超标准、超范围接待或者借机大吃大喝，适用第一百一十六条。</p>
<h3>3. 公款旅游</h3>
<p>公款旅游或者以学习培训、考察调研、职工疗养等为名变相公款旅游，改变公务行程借机旅游，参加所管理企业、下属单位组织的考察活动借机旅游，适用第一百一十五条。</p>
<h3>4. 违规操办婚丧喜庆事宜</h3>
<p>利用职权或者职务上的影响操办婚丧喜庆事宜造成不良影响的，适用第一百条；借机敛财或者有其他侵犯国家、集体和人民利益行为的，从重或者加重处分，直至开除党籍。</p>
<h3>5. 楼堂馆所与办公用房问题</h3>
<p>决定或者批准兴建、装修办公楼、培训中心等楼堂馆所，超标准配备、使用办公用房等，适用第一百一十九条；违反公务交通工具管理规定适用第一百一十七条；违反会议活动管理规定适用第一百一十八条。</p>
<h3>6. 违规发放津补贴福利</h3>
<p>违反有关规定自定薪酬或者滥发津贴、补贴、奖金、福利等，适用第一百一十四条。</p>
<p>提示：对上述行为，条例均规定对直接责任者和领导责任者追究责任，体现"一案双查"要求。</p>',NULL,8,1200,'["中央八项规定", "定性量纪", "廉洁纪律"]'::jsonb,2,'{"type":"ALL"}'::jsonb,0,2,1,now(),1,1,'/1/',1) ON CONFLICT DO NOTHING;
INSERT INTO t_learn_material (id,category_id,title,summary,file_type,file_url,content,file_size,page_count,duration_sec,tags,apply_level,visible_scope,need_audit,audit_status,audit_by,audit_time,version,upload_org_id,upload_org_path,create_by) VALUES (5,5,'党的六大纪律逐项解读','政治纪律、组织纪律、廉洁纪律、群众纪律、工作纪律、生活纪律的条款范围与典型违纪行为。',5,NULL,'<h2>党的六大纪律逐项解读</h2>
<p>《中国共产党纪律处分条例》分则按照六大纪律分类规定违纪行为及处分标准。</p>
<h3>一、政治纪律（第六章，第49-76条）</h3>
<p>政治纪律是最重要、最根本、最关键的纪律。典型违纪行为：在重大原则问题上不同党中央保持一致（第49条）；公开发表有严重政治问题的言论、妄议党中央大政方针（第51条）；在党内搞团团伙伙、结党营私（第54条）；对党不忠诚不老实，搞两面派、做两面人（第58条）；对抗组织审查，串供或者伪造、销毁、转移、隐匿证据（第63条）；干扰巡视巡察工作或者不落实巡视巡察整改要求（第62条）。</p>
<h3>二、组织纪律（第七章，第77-93条）</h3>
<p>典型违纪行为：违反民主集中制原则，个人或者少数人决定重大问题（第77条）；违反个人有关事项报告规定隐瞒不报、谈话函询时不如实说明问题（第81条）；在干部选拔任用中任人唯亲、跑官要官、突击提拔（第84条）；在选举中搞拉票助选等非组织活动（第83条）；侵犯党员表决权、选举权和被选举权（第87条）。</p>
<h3>三、廉洁纪律（第八章，第94-121条）</h3>
<p>典型违纪行为：收受可能影响公正执行公务的礼品礼金消费卡（第97条）；违规从事营利活动、经商办企业（第103条）；利用职权为亲属谋取利益（第104条）；公款旅游、公款宴请（第113、115条）；违规出入私人会所、持有高尔夫卡（第102条）；搞权色交易、钱色交易（第120条）。</p>
<h3>四、群众纪律（第九章，第122-129条）</h3>
<p>典型违纪行为：超标准超范围向群众筹资筹劳、摊派费用（第122条）；在社会保障、救灾救济款物分配中优亲厚友（第124条）；利用宗族或黑恶势力欺压群众、充当"保护伞"（第125条）；对群众诉求消极应付、推诿扯皮，对待群众态度恶劣（第126条）；不按规定公开党务政务侵犯群众知情权（第128条）。</p>
<h3>五、工作纪律（第十章，第130-149条）</h3>
<p>典型违纪行为：工作中不负责任、贯彻执行上级决策部署不力造成较大损失（第130条）；形式主义、官僚主义行为（第132条）；统计造假（第139条）；干预和插手市场经济活动、司法活动、执纪执法活动（第141、142条）；泄露纪律审查等保密事项（第144条）；在考试、录取工作中泄露试题、考场舞弊（第145条）。</p>
<h3>六、生活纪律（第十一章，第150-154条）</h3>
<p>典型违纪行为：生活奢靡、铺张浪费、贪图享乐、追求低级趣味（第150条）；与他人发生不正当性关系（第151条）；不重视家风建设，对配偶、子女及其配偶失管失教（第152条）；违背社会公序良俗，在公共场所、网络空间有不当言行（第153条）。</p>',NULL,14,2100,'["六大纪律", "条例解读"]'::jsonb,2,'{"type":"ALL"}'::jsonb,0,2,1,now(),1,1,'/1/',1) ON CONFLICT DO NOTHING;
INSERT INTO t_learn_material (id,category_id,title,summary,file_type,file_url,content,file_size,page_count,duration_sec,tags,apply_level,visible_scope,need_audit,audit_status,audit_by,audit_time,version,upload_org_id,upload_org_path,create_by) VALUES (6,6,'《中国共产党纪律处分条例》2023年修订要点解读','第三次修订的总体考虑与主要内容：新增16条、修改76条，2024年1月1日起施行。',5,NULL,'<h2>《中国共产党纪律处分条例》2023年修订要点解读</h2>
<p>2023年12月，党中央印发了修订后的《中国共产党纪律处分条例》。这是党的十八大以来党中央对这一条例的第三次修订。修订后的《条例》共158条，与2018年《条例》相比，新增16条、修改76条，自2024年1月1日起施行。</p>
<h3>一、修订的总体考虑</h3>
<p>全面贯彻习近平新时代中国特色社会主义思想和党的二十大精神，从党章这个总源头出发，坚持严的基调，坚持问题导向和目标导向相结合，与时俱进完善纪律规范，进一步严明政治纪律和政治规矩，带动各项纪律全面从严。</p>
<h3>二、主要修订内容</h3>
<ul>
<li><b>总则部分</b>：完善纪律处分运用规则，如第五条规定深化运用监督执纪"四种形态"，增加"谈话提醒、批评教育、责令检查、诫勉"等第一种形态处理方式；第十九条新增对轻微违纪、苗头性倾向性问题可以不予党纪处分的规定，落实"三个区分开来"。</li>
<li><b>政治纪律</b>：增加对搞投机钻营、结交政治骗子行为的处分规定（第五十五条）；增加对党员领导干部政绩观错位，搞劳民伤财的"形象工程""政绩工程"从重或者加重处分的规定（第五十七条）。</li>
<li><b>廉洁纪律</b>：完善对违规收送礼品礼金、以讲课费课题费咨询费等名义变相送礼行为的处分规定；增写对离职或者退（离）休后利用原职权影响谋利行为的处分条款（第一百零六条）。</li>
<li><b>群众纪律</b>：将"扶贫领域"修改为"乡村振兴领域"，在乡村振兴领域侵害群众利益的从重或者加重处分（第一百二十二条）。</li>
<li><b>工作纪律</b>：增加对统计造假、对统计造假失察行为的处分规定（第一百三十九条）；增加对滥用问责或者在问责工作中严重不负责任行为的处分规定（第一百三十七条）。</li>
</ul>
<h3>三、学习贯彻要求</h3>
<p>各级党委（党组）要担负起全面从严治党政治责任，把《条例》纳入党员、干部培训必修课；各级纪委（纪检组）要强化监督执纪问责，敢于善于斗争，严格执纪、精准执纪。</p>
<p>资料来源：中国政府网《中共中央印发〈中国共产党纪律处分条例〉》、共产党员网2023年新旧对照版。</p>',NULL,8,1200,'["条例解读", "修订要点", "2023修订"]'::jsonb,2,'{"type":"ALL"}'::jsonb,0,2,1,now(),1,1,'/1/',1) ON CONFLICT DO NOTHING;
INSERT INTO t_learn_material (id,category_id,title,summary,file_type,file_url,content,file_size,page_count,duration_sec,tags,apply_level,visible_scope,need_audit,audit_status,audit_by,audit_time,version,upload_org_id,upload_org_path,create_by) VALUES (7,8,'案例警示：违反中央八项规定精神典型案例剖析','违规收礼、公款旅游、大操大办婚宴三类典型案例的案情、定性与警示。',5,NULL,'<h2>案例警示：违反中央八项规定精神典型案例剖析</h2>
<p>以下案例类型依据中央纪委国家监委公开通报的常见情形整理，用于以案明纪、以案说法。</p>
<h3>案例一：违规收受管理服务对象礼金</h3>
<p><b>案情</b>：某国企部门负责人张某，在春节、中秋等节日期间多次收受供应商赠送的礼金和购物卡，合计数万元，并在设备采购中为该供应商提供帮助。</p>
<p><b>定性</b>：张某收受可能影响公正执行公务的礼金、消费卡，违反廉洁纪律，适用《中国共产党纪律处分条例》第九十七条；利用职权为他人谋取利益，视情节可认定受贿性质问题，涉嫌犯罪的移送司法机关。最终张某受到开除党籍处分。</p>
<p><b>警示</b>：礼尚往来有界限，"可能影响公正执行公务"是认定关键，与管理服务对象之间的财物往来必须一律拒绝。</p>
<h3>案例二：以考察培训为名公款旅游</h3>
<p><b>案情</b>：某单位以"学习考察"名义组织干部职工赴风景名胜区，实际行程以游览为主，费用由公款列支。</p>
<p><b>定性</b>：属于以学习培训、考察调研为名变相公款旅游，违反廉洁纪律，适用条例第一百一十五条，对直接责任者和领导责任者均给予党纪处分，并责令退赔相关费用。</p>
<p><b>警示</b>：变换名目、借壳旅游改变不了公款旅游的实质，组织者、批准者、参与者都要被追责。</p>
<h3>案例三：大操大办婚宴借机敛财</h3>
<p><b>案情</b>：某党员领导干部为其子操办婚宴，超出报备规模多桌宴请，邀请多名下属和管理服务对象参加并收受礼金。</p>
<p><b>定性</b>：利用职权或者职务上的影响操办婚丧喜庆事宜造成不良影响，适用条例第一百条；借机敛财的从重或者加重处分。</p>
<p><b>警示</b>：婚丧喜庆事宜要严格按规定报备，控制规模范围，严禁邀请管理服务对象并收受礼金。</p>',NULL,8,1500,'["案例警示", "以案明纪", "八项规定"]'::jsonb,2,'{"type":"ALL"}'::jsonb,0,2,1,now(),1,1,'/1/',1) ON CONFLICT DO NOTHING;
INSERT INTO t_learn_material (id,category_id,title,summary,file_type,file_url,content,file_size,page_count,duration_sec,tags,apply_level,visible_scope,need_audit,audit_status,audit_by,audit_time,version,upload_org_id,upload_org_path,create_by) VALUES (8,9,'《中国共产党纪律检查委员会工作条例》学习要点','纪委工作条例8章59条：职能定位、领导体制、主要任务、工作职责与自身建设要求。',5,NULL,'<h2>《中国共产党纪律检查委员会工作条例》学习要点</h2>
<p>2021年12月6日中共中央政治局会议审议批准，2021年12月24日中共中央发布。全文共8章59条，是规范党的纪律检查委员会工作的基础性党内法规。</p>
<h3>一、职能定位（第三条）</h3>
<p>党的各级纪律检查委员会是党内监督专责机关，是党推进全面从严治党、开展党风廉政建设和反腐败斗争的专门力量。主要任务是：维护党的章程和其他党内法规，检查党的理论和路线方针政策、党中央决策部署执行情况，协助党的委员会推进全面从严治党、加强党风建设和组织协调反腐败工作。</p>
<p>把坚决维护习近平总书记党中央的核心、全党的核心地位，维护党中央权威和集中统一领导作为最高政治原则和根本政治责任。</p>
<h3>二、领导体制（第五至七条）</h3>
<p>中央纪委（国家监委）在党中央领导下进行工作；地方各级纪委和基层纪委在同级党的委员会和上级纪律检查委员会双重领导下进行工作；坚持查办腐败案件以上级纪委领导为主。各级纪委与同级监委合署办公，实行一套工作机构、两个机关名称，履行纪律检查和国家监察两项职责。</p>
<h3>三、主要任务（第四章）</h3>
<p>坚定维护党章；检查党的理论和路线方针政策执行情况；协助同级党委推进全面从严治党；锲而不舍落实中央八项规定精神，驰而不息纠治形式主义、官僚主义、享乐主义和奢靡之风；协助党委组织协调反腐败工作，坚持把一体推进不敢腐、不能腐、不想腐作为反腐败斗争的基本方针。</p>
<h3>四、工作职责（第五章）</h3>
<p>纪委履行监督、执纪、问责职责。坚持把监督作为基本职责，精准有效运用监督执纪"四种形态"：第一种形态——谈话提醒、批评教育、责令检查、诫勉；第二种形态——警告、严重警告处分或者停职检查、调整职务等组织调整；第三种形态——撤销党内职务、留党察看、开除党籍处分及降职、撤职等处理；第四种形态——开除党籍、开除公职并移送司法机关。</p>
<h3>五、自身建设（第七章）</h3>
<p>纪检干部必须接受最严格的约束和监督，坚决防治"灯下黑"；严格执行打听案情、过问案件、说情干预问题报告登记制度；严格执行保密制度；离职后三年内不得从事与纪律检查工作相关的职业。</p>',NULL,10,1500,'["纪委工作条例", "党内法规"]'::jsonb,2,'{"type":"ALL"}'::jsonb,0,2,1,now(),1,1,'/1/',1) ON CONFLICT DO NOTHING;
INSERT INTO t_learn_material (id,category_id,title,summary,file_type,file_url,content,file_size,page_count,duration_sec,tags,apply_level,visible_scope,need_audit,audit_status,audit_by,audit_time,version,upload_org_id,upload_org_path,create_by) VALUES (9,10,'监督执纪“四种形态”详解','四种形态的具体内容、适用情形与实践要求，依据纪律处分条例第五条和纪委工作条例第三十一条。',5,NULL,'<h2>监督执纪"四种形态"详解</h2>
<p>监督执纪"四种形态"是全面从严治党的重要政策策略，体现惩前毖后、治病救人的方针，依据《中国共产党纪律处分条例》第五条和《中国共产党纪律检查委员会工作条例》第三十一条整理。</p>
<h3>第一种形态</h3>
<p>党员、干部有作风纪律方面的苗头性、倾向性问题或者轻微违纪问题，或者有一般违纪问题但具备免予处分情形的，按照规定进行谈话提醒、批评教育、责令检查等，或者予以诫勉。让"红红脸、出出汗"成为常态。</p>
<h3>第二种形态</h3>
<p>党员、干部有一般违纪问题，或者违纪问题严重但具有主动交代等从轻减轻处分情形的，按照规定给予警告、严重警告处分，或者建议单处、并处停职检查、调整职务、责令辞职、免职等处理。党纪轻处分、组织调整成为违纪处理的大多数。</p>
<h3>第三种形态</h3>
<p>党员、干部有严重违纪问题，或者严重违纪并构成严重职务违法的，按照规定给予撤销党内职务、留党察看、开除党籍处分，同时建议给予降职或者依法给予撤职、开除公职、调整其享受的待遇等处理。党纪重处分、重大职务调整的成为少数。</p>
<h3>第四种形态</h3>
<p>党员、干部严重违纪、涉嫌犯罪的，按照规定给予开除党籍处分，同时依法给予开除公职、调整或者取消其享受的待遇等处理，再移送司法机关依法追究刑事责任。严重违纪涉嫌犯罪追究刑事责任的成为极少数。</p>
<h3>实践要求</h3>
<p>运用"四种形态"要综合考虑错误性质、情节后果、主观态度等因素，做到依规依纪依法、精准有效，把思想政治工作贯穿始终，实现政治效果、纪法效果、社会效果有机统一。</p>',NULL,6,900,'["四种形态", "监督执纪"]'::jsonb,2,'{"type":"ALL"}'::jsonb,0,2,1,now(),1,1,'/1/',1) ON CONFLICT DO NOTHING;
INSERT INTO t_learn_material (id,category_id,title,summary,file_type,file_url,content,file_size,page_count,duration_sec,tags,apply_level,visible_scope,need_audit,audit_status,audit_by,audit_time,version,upload_org_id,upload_org_path,create_by) VALUES (10,10,'《监督执纪工作规则》核心程序：线索处置到案件审理','监督执纪工作规则（2019）要点：线索四类处置方式、谈话函询、初步核实、立案审查、案件审理。',5,NULL,'<h2>《中国共产党纪律检查机关监督执纪工作规则》核心程序</h2>
<p>《中国共产党纪律检查机关监督执纪工作规则》于2019年1月由中共中央办公厅印发施行，共10章77条，是纪检监察机关监督执纪工作的基本遵循。核心程序要点如下：</p>
<h3>一、领导体制</h3>
<p>监督执纪工作实行分级负责制，坚持纪律检查工作双重领导体制，监督执纪工作以上级纪委领导为主，线索处置、立案审查等在向同级党委报告的同时应当向上级纪委报告。</p>
<h3>二、线索管理与处置</h3>
<p>纪检监察机关对问题线索实行集中管理、动态更新、定期汇总核对。承办部门应当结合问题线索所涉及地区、部门、单位总体情况，综合分析，按照<b>谈话函询、初步核实、暂存待查、予以了结</b>四类方式进行处置，做到件件有着落。</p>
<h3>三、谈话函询</h3>
<p>采取谈话函询方式处置问题线索，应当拟订谈话函询方案和相关工作预案，按程序报批。谈话函询结果根据情况区别处理：反映不实或者没有证据证明存在问题的予以采信了结；问题轻微不需要追究党纪责任的采取谈话提醒、批评教育等方式处理；反映问题比较具体但被反映人予以否认或者说明存在明显问题的，一般应当再次谈话函询或者进行初步核实。</p>
<h3>四、初步核实</h3>
<p>对涉嫌违纪需要追究党纪责任的问题线索，应当进行初步核实。初步核实工作结束后，核查组应当撰写初步核实情况报告，提出处理建议：确有违纪事实需要追究党纪责任的，予以立案审查；问题不属实或者没有证据证明存在问题的，予以了结；问题轻微的，予以谈话提醒、批评教育等处理。</p>
<h3>五、立案审查</h3>
<p>对符合立案条件的，承办部门应当起草立案审查呈批报告，经纪检监察机关主要负责人审批，报同级党委（党组）主要负责人批准，予以立案审查。审查期间严格依规依纪收集证据，查明事实，严禁以威胁、引诱、欺骗等非法方式收集证据。</p>
<h3>六、案件审理</h3>
<p>审查结束后移送审理。审理工作坚持事实清楚、证据确凿、定性准确、处理恰当、手续完备、程序合规的基本要求，处分决定经集体审议后按规定报批，并向被审查人宣布，保障其申辩和申诉权利。</p>
<h3>七、监督管理</h3>
<p>纪检监察机关应当严格干部准入制度，严格执行回避制度、保密制度和安全责任制；对执纪违纪、执法违法者"零容忍"，坚决防止"灯下黑"。</p>',NULL,10,1500,'["监督执纪工作规则", "业务规程", "审查程序"]'::jsonb,2,'{"type":"ALL"}'::jsonb,0,2,1,now(),1,1,'/1/',1) ON CONFLICT DO NOTHING;
