INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (1,2,1,'《中国共产党纪律处分条例》（2023年修订）自何时起施行？','0e4f2198b2ab63070684efdd0f1fa02a','[{"key": "A", "content": "2023年12月8日"}, {"key": "B", "content": "2023年12月19日"}, {"key": "C", "content": "2024年1月1日"}, {"key": "D", "content": "2024年3月1日"}]'::jsonb,'{"keys": ["C"]}'::jsonb,'条例第一百五十八条规定：本条例自2024年1月1日起施行。2023年12月8日为政治局会议审议修订时间，12月19日为发布时间。',1,2,'["总则", "施行时间"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第一百五十八条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (2,2,1,'党员受到警告处分（　）内，不得在党内提拔职务或者进一步使用，也不得向党外组织推荐担任高于其原任职务的党外职务或者进一步使用。','50b6e7fc3b3b224fa7dfe0d5fe3c90df','[{"key": "A", "content": "半年"}, {"key": "B", "content": "一年"}, {"key": "C", "content": "一年半"}, {"key": "D", "content": "二年"}]'::jsonb,'{"keys": ["B"]}'::jsonb,'条例第十条规定：党员受到警告处分一年内、受到严重警告处分一年半内，不得在党内提拔职务或者进一步使用。',1,2,'["总则", "处分影响期"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第十条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (3,2,1,'留党察看处分，分为留党察看一年、留党察看二年。留党察看期限最长不得超过（　）。','a6540b0be483e09c16a7b16ef1fc9ae2','[{"key": "A", "content": "一年"}, {"key": "B", "content": "一年半"}, {"key": "C", "content": "二年"}, {"key": "D", "content": "三年"}]'::jsonb,'{"keys": ["C"]}'::jsonb,'条例第十二条规定：留党察看期限最长不得超过二年。受留党察看处分期间没有表决权、选举权和被选举权。',1,2,'["总则", "留党察看"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第十二条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (4,2,1,'党员受到开除党籍处分，（　）内不得重新入党，也不得推荐担任与其原任职务相当或者高于其原任职务的党外职务。','a3465e1b3d2d48f96e82312446806d30','[{"key": "A", "content": "三年"}, {"key": "B", "content": "四年"}, {"key": "C", "content": "五年"}, {"key": "D", "content": "终身"}]'::jsonb,'{"keys": ["C"]}'::jsonb,'条例第十三条规定：党员受到开除党籍处分，五年内不得重新入党。另有规定不准重新入党的，依照规定。',1,2,'["总则", "开除党籍"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第十三条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (5,2,1,'一人有《中国共产党纪律处分条例》规定的两种以上应当受到党纪处分的违纪行为，应当合并处理，按其数种违纪行为中应当受到的最高处分（　）给予处分。','f15a5458f3b979a76d3b2063034de67a','[{"key": "A", "content": "加重一档"}, {"key": "B", "content": "从重"}, {"key": "C", "content": "减轻一档"}, {"key": "D", "content": "分别执行"}]'::jsonb,'{"keys": ["A"]}'::jsonb,'条例第二十四条规定：一人有两种以上违纪行为的应当合并处理，按其最高处分加重一档给予处分；其中一种应当受到开除党籍处分的，应当给予开除党籍处分。',2,2,'["总则", "合并处理"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第二十四条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (6,2,2,'对党员的纪律处分种类包括（　）。','8e57545879db0d234ed0ca25c704608a','[{"key": "A", "content": "警告"}, {"key": "B", "content": "严重警告"}, {"key": "C", "content": "撤销党内职务"}, {"key": "D", "content": "留党察看"}, {"key": "E", "content": "开除党籍"}]'::jsonb,'{"keys": ["A", "B", "C", "D", "E"]}'::jsonb,'条例第八条规定了五种党纪处分：警告、严重警告、撤销党内职务、留党察看、开除党籍。对党组织的处理为改组、解散。',1,4,'["总则", "处分种类"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第八条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (7,2,2,'党的纪律处分工作应当遵循的原则包括（　）。','9388863b823699f246d595dc0fe9cedd','[{"key": "A", "content": "坚持党要管党、全面从严治党"}, {"key": "B", "content": "党纪面前一律平等"}, {"key": "C", "content": "实事求是"}, {"key": "D", "content": "民主集中制"}, {"key": "E", "content": "惩前毖后、治病救人"}]'::jsonb,'{"keys": ["A", "B", "C", "D", "E"]}'::jsonb,'条例第四条规定了纪律处分工作应遵循的五项原则。',2,4,'["总则", "处分原则"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第四条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (8,2,2,'根据条例第十七条，下列情形中可以从轻或者减轻处分的有（　）。','d82c27d5b7bcbd1fdc24ae8c4016074f','[{"key": "A", "content": "主动交代本人应当受到党纪处分的问题"}, {"key": "B", "content": "检举同案人或者其他人应当受到党纪处分或者法律追究的问题，经查证属实"}, {"key": "C", "content": "主动挽回损失、消除不良影响或者有效阻止危害结果发生"}, {"key": "D", "content": "拒不上交或者退赔违纪所得"}]'::jsonb,'{"keys": ["A", "B", "C"]}'::jsonb,'第十七条列举了六种从轻或减轻处分情形，D项属于第二十条规定的应当从重或者加重处分的情形。',2,4,'["总则", "从轻减轻"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第十七条、第二十条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (9,2,3,'党员受到严重警告处分一年半内，不得在党内提拔职务或者进一步使用。','9b559c53360cdf29f0d50f089745a934','[{"key": "T", "content": "正确"}, {"key": "F", "content": "错误"}]'::jsonb,'{"keys": ["T"]}'::jsonb,'条例第十条规定：警告处分一年内、严重警告处分一年半内，不得在党内提拔职务或者进一步使用。',1,2,'["总则", "处分影响期"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第十条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (10,2,3,'党员受留党察看处分期间，仍然享有表决权、选举权和被选举权。','614c7d53128f375d266056200e5a6624','[{"key": "T", "content": "正确"}, {"key": "F", "content": "错误"}]'::jsonb,'{"keys": ["F"]}'::jsonb,'条例第十二条规定：党员受留党察看处分期间，没有表决权、选举权和被选举权，其党内职务自然撤销。',1,2,'["总则", "留党察看"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第十二条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (11,2,3,'条例规定的只有开除党籍处分一个档次的违纪行为，不适用减轻处分的规定。','dfc617b572aa2f80666eb384ccd12b2e','[{"key": "T", "content": "正确"}, {"key": "F", "content": "错误"}]'::jsonb,'{"keys": ["T"]}'::jsonb,'条例第二十三条规定：减轻处分是指在处分幅度以外减轻一档给予处分；只有开除党籍处分一个档次的违纪行为，不适用减轻处分的规定。',2,2,'["总则", "减轻处分"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第二十三条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (12,2,4,'对党员的纪律处分种类为：警告、严重警告、撤销党内职务、______、开除党籍。','c7b6e67bce5c7677936851c8f17d777d',NULL,'{"blanks": [["留党察看"]]}'::jsonb,'条例第八条规定的五种党纪处分之一，位于撤销党内职务与开除党籍之间。',1,4,'["总则", "处分种类"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第八条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (13,2,4,'深化运用监督执纪“四种形态”，经常开展批评和自我批评，及时进行谈话提醒、批评教育、责令检查、诫勉，让“______”成为常态。','c42ae7aa598f390593896b5f8bebc890',NULL,'{"blanks": [["红红脸、出出汗", "红脸出汗"]]}'::jsonb,'条例第五条规定，让“红红脸、出出汗”成为常态，体现抓早抓小、防微杜渐。',2,4,'["总则", "四种形态"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第五条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (14,2,5,'简述监督执纪“四种形态”的基本内容。','03af365c2bcc95df445b75defa1b406f',NULL,'{"reference": "第一种形态：经常开展批评和自我批评，及时进行谈话提醒、批评教育、责令检查、诫勉，让“红红脸、出出汗”成为常态；第二种形态：党纪轻处分、组织调整成为违纪处理的大多数；第三种形态：党纪重处分、重大职务调整的成为少数；第四种形态：严重违纪涉嫌犯罪追究刑事责任的成为极少数。", "points": ["第一种形态：谈话提醒、批评教育、责令检查、诫勉，红脸出汗成为常态", "第二种形态：党纪轻处分、组织调整成为大多数", "第三种形态：党纪重处分、重大职务调整成为少数", "第四种形态：严重违纪涉嫌犯罪追究刑事责任成为极少数"]}'::jsonb,'条例第五条对“四种形态”作出明确规定，体现惩前毖后、治病救人，抓早抓小、防微杜渐。',2,10,'["总则", "四种形态"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第五条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (15,3,1,'对抗组织审查，串供或者伪造、销毁、转移、隐匿证据的，情节严重的，给予（　）处分。','3531122a6ab4c109987de7a217960661','[{"key": "A", "content": "严重警告"}, {"key": "B", "content": "撤销党内职务"}, {"key": "C", "content": "留党察看"}, {"key": "D", "content": "开除党籍"}]'::jsonb,'{"keys": ["D"]}'::jsonb,'条例第六十三条规定：对抗组织审查，情节严重的，给予开除党籍处分。该行为违反政治纪律。',2,2,'["政治纪律", "对抗组织审查"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第六十三条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (16,3,1,'收受可能影响公正执行公务的礼品、礼金、消费卡（券）和有价证券、股权、其他金融产品等财物，情节较重的，给予（　）处分。','dd9367793d283cd33408248b3042b8a5','[{"key": "A", "content": "警告或者严重警告"}, {"key": "B", "content": "撤销党内职务或者留党察看"}, {"key": "C", "content": "开除党籍"}, {"key": "D", "content": "批评教育或者诫勉"}]'::jsonb,'{"keys": ["B"]}'::jsonb,'条例第九十七条规定：收受可能影响公正执行公务的财物，情节较重的给予撤销党内职务或者留党察看处分；情节严重的给予开除党籍处分。',2,2,'["廉洁纪律", "收受礼品礼金"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第九十七条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (17,3,1,'利用职权或者职务上的影响操办婚丧喜庆事宜，在社会上造成不良影响的，情节严重的，给予（　）处分。','1afedcfd0b3f76514b56954ab04cc91b','[{"key": "A", "content": "撤销党内职务"}, {"key": "B", "content": "留党察看"}, {"key": "C", "content": "开除党籍"}, {"key": "D", "content": "严重警告"}]'::jsonb,'{"keys": ["A"]}'::jsonb,'条例第一百条规定：利用职权或者职务上的影响操办婚丧喜庆事宜造成不良影响的，给予警告或者严重警告处分；情节严重的，给予撤销党内职务处分；借机敛财的从重或者加重处分，直至开除党籍。',3,2,'["廉洁纪律", "婚丧喜庆"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第一百条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (18,3,1,'在党内组织秘密集团或者组织其他分裂党的活动的，给予（　）处分。','d1f7c2ec00e95bc29bc1096ad634fed6','[{"key": "A", "content": "严重警告"}, {"key": "B", "content": "撤销党内职务"}, {"key": "C", "content": "留党察看"}, {"key": "D", "content": "开除党籍"}]'::jsonb,'{"keys": ["D"]}'::jsonb,'条例第五十三条规定：在党内组织秘密集团或者组织其他分裂党的活动的，给予开除党籍处分；参加的，给予留党察看或者开除党籍处分。',2,2,'["政治纪律", "分裂活动"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第五十三条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (19,3,1,'党员领导干部不重视家风建设，对配偶、子女及其配偶失管失教，造成不良影响或者严重后果的，属于违反（　）的行为。','b0b3a7f535d23c83cfad9cda9e2e849b','[{"key": "A", "content": "政治纪律"}, {"key": "B", "content": "组织纪律"}, {"key": "C", "content": "廉洁纪律"}, {"key": "D", "content": "生活纪律"}]'::jsonb,'{"keys": ["D"]}'::jsonb,'条例第一百五十二条规定：党员领导干部不重视家风建设，对配偶、子女及其配偶失管失教，属于违反生活纪律的行为。',2,2,'["生活纪律", "家风建设"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第一百五十二条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (20,3,2,'党的六大纪律包括（　）。','b111d0c2ec33cbba1a10f8559a2a20b6','[{"key": "A", "content": "政治纪律"}, {"key": "B", "content": "组织纪律"}, {"key": "C", "content": "廉洁纪律"}, {"key": "D", "content": "群众纪律"}, {"key": "E", "content": "工作纪律"}, {"key": "F", "content": "生活纪律"}]'::jsonb,'{"keys": ["A", "B", "C", "D", "E", "F"]}'::jsonb,'条例分则第六章至第十一章分别规定违反政治纪律、组织纪律、廉洁纪律、群众纪律、工作纪律、生活纪律行为的处分。',1,4,'["六大纪律", "分则结构"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第六章至第十一章',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (21,3,2,'下列行为中，属于违反廉洁纪律的有（　）。','f2e1348c078a65712cbab47c3eb1fb57','[{"key": "A", "content": "收受可能影响公正执行公务的礼品、礼金、消费卡（券）"}, {"key": "B", "content": "违反有关规定经商办企业、从事营利活动"}, {"key": "C", "content": "公款旅游或者以考察培训为名变相公款旅游"}, {"key": "D", "content": "对待群众态度恶劣、简单粗暴，造成不良影响"}]'::jsonb,'{"keys": ["A", "B", "C"]}'::jsonb,'A项适用第九十七条、B项适用第一百零三条、C项适用第一百一十五条，均属廉洁纪律；D项适用第一百二十六条，属于违反群众纪律。',2,4,'["廉洁纪律", "群众纪律"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第九十七、一百零三、一百一十五、一百二十六条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (22,3,2,'根据条例规定，下列属于违反组织纪律行为的有（　）。','c46c5f172b76e5d82e703476369498d8','[{"key": "A", "content": "违反个人有关事项报告规定，隐瞒不报"}, {"key": "B", "content": "在组织进行谈话函询时，不如实向组织说明问题"}, {"key": "C", "content": "篡改、伪造个人档案资料"}, {"key": "D", "content": "不按照有关规定向组织请示、报告重大事项"}]'::jsonb,'{"keys": ["A", "B", "C"]}'::jsonb,'A、B项适用第八十一条，C项篡改伪造档案适用第八十一条第三款，均属组织纪律；D项适用第六十一条，属于违反政治纪律。',2,4,'["组织纪律", "政治纪律"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第八十一条、第六十一条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (23,3,3,'违反有关规定组织、参加用公款支付的宴请、娱乐、健身活动的，只对直接责任者给予处分，不追究领导责任者的责任。','d6215b6691871001360ec9b043c7b7e9','[{"key": "T", "content": "正确"}, {"key": "F", "content": "错误"}]'::jsonb,'{"keys": ["F"]}'::jsonb,'条例第一百一十三条规定，对直接责任者和领导责任者都要视情节给予处分，体现“一案双查”。',2,2,'["廉洁纪律", "公款宴请"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第一百一十三条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (24,3,3,'利用宗族或者黑恶势力等欺压群众，或者纵容涉黑涉恶活动、为黑恶势力充当“保护伞”的，给予撤销党内职务或者留党察看处分；情节严重的，给予开除党籍处分。','4aa3ad6042ec99af94d76dd736503777','[{"key": "T", "content": "正确"}, {"key": "F", "content": "错误"}]'::jsonb,'{"keys": ["T"]}'::jsonb,'条例第一百二十五条对此作出明确规定，该行为违反群众纪律。',2,2,'["群众纪律", "保护伞"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第一百二十五条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (25,3,3,'党员有嫖娼或者吸食、注射毒品等丧失党员条件，严重败坏党的形象行为的，应当给予开除党籍处分。','f6cfccbae9750ff12654eae39e1e7a2b','[{"key": "T", "content": "正确"}, {"key": "F", "content": "错误"}]'::jsonb,'{"keys": ["T"]}'::jsonb,'条例第三十条第三款对此作出明确规定。',1,2,'["违法犯罪党员处理", "开除党籍"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第三十条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (26,3,4,'在重大原则问题上不同党中央保持一致且有实际言论、行为或者造成不良后果的，违反了党的______纪律。','156aa556d9e361822056c9bfd583f07d',NULL,'{"blanks": [["政治"]]}'::jsonb,'条例第四十九条规定的行为违反政治纪律。政治纪律是最重要、最根本、最关键的纪律。',1,4,'["政治纪律"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第四十九条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (27,3,4,'违反有关规定取得、持有、实际使用运动健身卡、会所和俱乐部会员卡、高尔夫球卡等各种消费卡（券），或者违反有关规定出入______，属于违反廉洁纪律的行为。','93c18b5f4fa6ff32c0913a7b38eba8e6',NULL,'{"blanks": [["私人会所"]]}'::jsonb,'条例第一百零二条规定：违反有关规定出入私人会所，情节较重的，给予警告或者严重警告处分；情节严重的，给予撤销党内职务或者留党察看处分。',2,4,'["廉洁纪律", "私人会所"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第一百零二条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (28,3,5,'简述《中国共产党纪律处分条例》规定的违反群众纪律行为的主要表现（列举四项以上）。','dfb8c6ef2ee24fb23c892140ac51339b',NULL,'{"reference": "主要表现包括：超标准、超范围向群众筹资筹劳、摊派费用，加重群众负担；违反有关规定扣留、收缴群众款物或者处罚群众；克扣群众财物或者拖欠群众钱款；在管理、服务活动中违反有关规定收取费用；在办理涉及群众事务时刁难群众、吃拿卡要；在社会保障、救灾救济款物分配等事项中优亲厚友、明显有失公平；利用宗族或者黑恶势力欺压群众、充当“保护伞”；对群众诉求消极应付、推诿扯皮；不按照规定公开党务政务，侵犯群众知情权等。", "points": ["超标准超范围筹资筹劳、摊派费用", "扣留收缴群众款物、克扣拖欠群众财物钱款", "管理服务中违规收费、刁难群众吃拿卡要", "款物分配中优亲厚友、有失公平", "纵容涉黑涉恶、充当保护伞", "消极应付群众诉求、不公开党务政务侵犯知情权"]}'::jsonb,'条例第九章（第一百二十二条至第一百二十九条）对违反群众纪律行为的处分作出规定，在乡村振兴领域有侵害群众利益行为的从重或者加重处分。',2,10,'["群众纪律", "分则"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）第九章',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (29,5,1,'中央八项规定是哪一年审议通过的？','0eb4408829314cd46e19384a8347bdd5','[{"key": "A", "content": "2012年"}, {"key": "B", "content": "2013年"}, {"key": "C", "content": "2017年"}, {"key": "D", "content": "2022年"}]'::jsonb,'{"keys": ["A"]}'::jsonb,'2012年12月4日，十八届中共中央政治局会议审议通过《十八届中央政治局关于改进工作作风、密切联系群众的八项规定》。',1,2,'["八项规定", "基础知识"]'::jsonb,'中央八项规定及其实施细则',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (30,5,1,'下列哪一项不属于中央八项规定的主要内容？','9ab4797eb02ed4985e360bbb07a34b2e','[{"key": "A", "content": "改进调查研究"}, {"key": "B", "content": "精简会议活动"}, {"key": "C", "content": "规范出访活动"}, {"key": "D", "content": "增加新闻报道数量和时长"}]'::jsonb,'{"keys": ["D"]}'::jsonb,'八项规定要求改进新闻报道，进一步压缩报道的数量、字数、时长，而非增加。八个方面为：改进调查研究、精简会议活动、精简文件简报、规范出访活动、改进警卫工作、改进新闻报道、严格文稿发表、厉行勤俭节约。',1,2,'["八项规定", "主要内容"]'::jsonb,'中央八项规定及其实施细则',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (31,5,1,'按照中央八项规定实施细则，各部门召开本系统全国性会议，每年不超过（　）次。','89bd145c28b70d9915c91013ee4197b0','[{"key": "A", "content": "1"}, {"key": "B", "content": "2"}, {"key": "C", "content": "3"}, {"key": "D", "content": "4"}]'::jsonb,'{"keys": ["A"]}'::jsonb,'实施细则规定：各部门召开本系统全国性会议，每年不超过1次；全国性会议人数不超过300人，时间不超过2天。',2,2,'["八项规定", "实施细则", "会议活动"]'::jsonb,'中央八项规定及其实施细则',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (32,5,1,'中央八项规定要求改进调查研究，到基层调研应当做到（　）。','fc8ab90b9433e19e42ae8ef256261c95','[{"key": "A", "content": "安排群众迎送，营造氛围"}, {"key": "B", "content": "轻车简从、减少陪同、简化接待"}, {"key": "C", "content": "铺设迎宾地毯，摆放花草"}, {"key": "D", "content": "安排宴请，上高档菜肴"}]'::jsonb,'{"keys": ["B"]}'::jsonb,'八项规定第一条规定：要轻车简从、减少陪同、简化接待，不张贴悬挂标语横幅，不安排群众迎送，不铺设迎宾地毯，不摆放花草，不安排宴请。',1,2,'["八项规定", "调查研究"]'::jsonb,'中央八项规定及其实施细则',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (33,5,2,'中央八项规定的内容包括（　）。','fdbe2f91c9b74dbeb9e258c3d41d3263','[{"key": "A", "content": "改进调查研究"}, {"key": "B", "content": "精简会议活动、精简文件简报"}, {"key": "C", "content": "规范出访活动"}, {"key": "D", "content": "改进警卫工作、改进新闻报道"}, {"key": "E", "content": "严格文稿发表"}, {"key": "F", "content": "厉行勤俭节约"}]'::jsonb,'{"keys": ["A", "B", "C", "D", "E", "F"]}'::jsonb,'中央八项规定共八个方面：改进调查研究、精简会议活动、精简文件简报、规范出访活动、改进警卫工作、改进新闻报道、严格文稿发表、厉行勤俭节约。',1,4,'["八项规定", "主要内容"]'::jsonb,'中央八项规定及其实施细则',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (34,5,2,'下列属于违反中央八项规定精神典型问题的有（　）。','445a3fb9942dd0837cbdfbe43ff36dd0','[{"key": "A", "content": "违规公款吃喝"}, {"key": "B", "content": "公款旅游或者变相公款旅游"}, {"key": "C", "content": "违规收送礼品礼金"}, {"key": "D", "content": "超标准配备、使用办公用房"}]'::jsonb,'{"keys": ["A", "B", "C", "D"]}'::jsonb,'上述行为分别适用纪律处分条例第一百零一条、第一百一十三条、第一百一十五条、第九十七条、第一百一十九条，均属违反中央八项规定精神的典型问题。',2,4,'["八项规定", "违纪类型"]'::jsonb,'《中国共产党纪律处分条例》（2023年修订）相关条款',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (35,5,3,'中央八项规定实施细则规定，会议活动现场布置要简朴，工作会议一律不摆花草、不制作背景板。','55a870b7a1e57597217f8160a3f1e113','[{"key": "T", "content": "正确"}, {"key": "F", "content": "错误"}]'::jsonb,'{"keys": ["T"]}'::jsonb,'实施细则第八条严格控制会议活动经费：会议活动现场布置要简朴，工作会议一律不摆花草、不制作背景板，严禁以任何名义发放纪念品。',2,2,'["八项规定", "实施细则", "会议活动"]'::jsonb,'中央八项规定及其实施细则',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (36,5,3,'中央八项规定只适用于中央政治局委员，与普通党员干部无关。','bb83a0d48b365ff66e078599c1574aee','[{"key": "T", "content": "正确"}, {"key": "F", "content": "错误"}]'::jsonb,'{"keys": ["F"]}'::jsonb,'中央八项规定精神面向全党，是全体党员、干部必须遵守的铁规矩。《纪律处分条例》第七条明确重点查处违反中央八项规定精神的问题，各级纪委协助党委锲而不舍落实中央八项规定精神。',1,2,'["八项规定", "适用范围"]'::jsonb,'中央八项规定及其实施细则',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (37,5,3,'按照中央八项规定实施细则，举办会议活动严禁以任何名义发放纪念品。','53609c4559c33405ea9038d2c89e3f36','[{"key": "T", "content": "正确"}, {"key": "F", "content": "错误"}]'::jsonb,'{"keys": ["T"]}'::jsonb,'实施细则第八条规定：严格控制会议活动经费，严禁以任何名义发放纪念品。',2,2,'["八项规定", "实施细则"]'::jsonb,'中央八项规定及其实施细则',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (38,5,4,'中央八项规定要求，要厉行______，严格遵守廉洁从政有关规定，严格执行住房、车辆配备等有关工作和生活待遇的规定。','0db807548281fda015561cfd037b84ae',NULL,'{"blanks": [["勤俭节约"]]}'::jsonb,'八项规定第八条：要厉行勤俭节约，严格遵守廉洁从政有关规定。',1,4,'["八项规定", "勤俭节约"]'::jsonb,'中央八项规定及其实施细则',2,1,now(),1) ON CONFLICT DO NOTHING;
