INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (40,5,5,'简述中央八项规定八个方面的主要内容。','be3a67323f33130b037cba4c475e7182',NULL,'{"reference": "一是改进调查研究，深入基层了解真实情况，轻车简从、减少陪同、简化接待；二是精简会议活动，切实改进会风，开短会、讲短话；三是精简文件简报，切实改进文风；四是规范出访活动，合理安排出访，严格控制随行人员；五是改进警卫工作，减少交通管制，一般不得封路、不清场闭馆；六是改进新闻报道，压缩报道数量、字数、时长；七是严格文稿发表，个人不公开出版著作、讲话单行本，不发贺信贺电，不题词题字；八是厉行勤俭节约，严格遵守廉洁从政有关规定。", "points": ["改进调查研究", "精简会议活动", "精简文件简报", "规范出访活动", "改进警卫工作", "改进新闻报道", "严格文稿发表", "厉行勤俭节约"]}'::jsonb,'2012年12月4日中央政治局会议审议通过，八个方面内容须准确记忆。',2,10,'["八项规定", "主要内容"]'::jsonb,'中央八项规定及其实施细则',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (41,7,1,'《中国共产党纪律检查委员会工作条例》规定，党的各级纪律检查委员会是党内监督（　）机关。','263d7eee84194dd7fdccd71e5f1a4e4c','[{"key": "A", "content": "专责"}, {"key": "B", "content": "主要"}, {"key": "C", "content": "专门"}, {"key": "D", "content": "专职"}]'::jsonb,'{"keys": ["A"]}'::jsonb,'条例第三条规定：党的各级纪律检查委员会是党内监督专责机关，是党推进全面从严治党、开展党风廉政建设和反腐败斗争的专门力量。',2,2,'["纪委工作条例", "职能定位"]'::jsonb,'《中国共产党纪律检查委员会工作条例》第三条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (42,7,1,'党的地方各级纪律检查委员会和基层纪律检查委员会在（　）双重领导下进行工作。','4d458cb26d25c86798f6e59ee4e6dfdd','[{"key": "A", "content": "同级党的委员会和上级纪律检查委员会"}, {"key": "B", "content": "上级党的委员会和上级纪律检查委员会"}, {"key": "C", "content": "同级党的委员会和同级人民政府"}, {"key": "D", "content": "上级纪律检查委员会和同级人民政府"}]'::jsonb,'{"keys": ["A"]}'::jsonb,'条例第六条规定：地方各级纪委和基层纪委在同级党的委员会和上级纪律检查委员会双重领导下进行工作，坚持查办腐败案件以上级纪委领导为主。',1,2,'["纪委工作条例", "领导体制"]'::jsonb,'《中国共产党纪律检查委员会工作条例》第六条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (43,7,1,'纪检监察机关对问题线索的处置方式不包括（　）。','8ba29928f27e4b11d02c05eb68ea60db','[{"key": "A", "content": "谈话函询"}, {"key": "B", "content": "初步核实"}, {"key": "C", "content": "暂存待查"}, {"key": "D", "content": "不经核实直接移送司法机关"}]'::jsonb,'{"keys": ["D"]}'::jsonb,'按照《监督执纪工作规则》，问题线索按照谈话函询、初步核实、暂存待查、予以了结四类方式处置；涉嫌犯罪的须经审查调查程序后依法移送，不能不经核实直接移送。',2,2,'["监督执纪工作规则", "线索处置"]'::jsonb,'《中国共产党纪律检查机关监督执纪工作规则》',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (44,7,1,'党的纪律检查委员会与监察委员会合署办公，实行一套工作机构、（　）机关名称。','b66c25254073bd5bed2534e344202ebe','[{"key": "A", "content": "一个"}, {"key": "B", "content": "两个"}, {"key": "C", "content": "三个"}, {"key": "D", "content": "四个"}]'::jsonb,'{"keys": ["B"]}'::jsonb,'条例第七条规定：实行一套工作机构、两个机关名称，履行党的纪律检查和国家监察两项职责。',1,2,'["纪委工作条例", "合署办公"]'::jsonb,'《中国共产党纪律检查委员会工作条例》第七条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (45,7,2,'党的各级纪律检查委员会的主要任务包括（　）。','3cd0349c81b8225e9876a9f1971a420f','[{"key": "A", "content": "维护党的章程和其他党内法规"}, {"key": "B", "content": "检查党的理论和路线方针政策、党中央决策部署执行情况"}, {"key": "C", "content": "协助党的委员会推进全面从严治党、加强党风建设和组织协调反腐败工作"}, {"key": "D", "content": "研究制定国民经济和社会发展计划"}]'::jsonb,'{"keys": ["A", "B", "C"]}'::jsonb,'条例第三条规定了纪委三项主要任务，D项不属于纪委职责。',2,4,'["纪委工作条例", "主要任务"]'::jsonb,'《中国共产党纪律检查委员会工作条例》第三条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (46,7,2,'纪检监察机关对问题线索的处置方式包括（　）。','cc6d14a84c9741333fb6799651921195','[{"key": "A", "content": "谈话函询"}, {"key": "B", "content": "初步核实"}, {"key": "C", "content": "暂存待查"}, {"key": "D", "content": "予以了结"}]'::jsonb,'{"keys": ["A", "B", "C", "D"]}'::jsonb,'《监督执纪工作规则》规定，对问题线索按照谈话函询、初步核实、暂存待查、予以了结四类方式分类处置，做到件件有着落。',1,4,'["监督执纪工作规则", "线索处置"]'::jsonb,'《中国共产党纪律检查机关监督执纪工作规则》',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (47,7,3,'党的各级纪律检查委员会把坚决维护习近平总书记党中央的核心、全党的核心地位，维护党中央权威和集中统一领导作为最高政治原则和根本政治责任。','6dc14c0921f69026b98461e720cab8b6','[{"key": "T", "content": "正确"}, {"key": "F", "content": "错误"}]'::jsonb,'{"keys": ["T"]}'::jsonb,'《中国共产党纪律检查委员会工作条例》第三条对此作出明确规定。',1,2,'["纪委工作条例", "两个维护"]'::jsonb,'《中国共产党纪律检查委员会工作条例》第三条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (48,7,3,'纪检干部离职的，三年内不得从事与纪律检查工作相关的职业。','ae1ca02984132719c791312aabc3f3a2','[{"key": "T", "content": "正确"}, {"key": "F", "content": "错误"}]'::jsonb,'{"keys": ["T"]}'::jsonb,'《中国共产党纪律检查委员会工作条例》第五十三条规定：纪检干部离职的，应当严格遵守有关离职后从业限制的规定，三年内不得从事与纪律检查工作相关的职业。',3,2,'["纪委工作条例", "队伍建设"]'::jsonb,'《中国共产党纪律检查委员会工作条例》第五十三条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (49,7,3,'监督执纪工作坚持双重领导体制，上级纪委不能改变下级纪委作出的错误或者不当的决定。','eb1d12ec062ee3dbb2a200e2a184016e','[{"key": "T", "content": "正确"}, {"key": "F", "content": "错误"}]'::jsonb,'{"keys": ["F"]}'::jsonb,'条例第六条规定：上级纪委加强对下级纪委的领导，可以按照程序改变下级纪委作出的错误或者不当的决定，必要时直接审查或者组织、指挥审查下级纪委管辖范围内有重大影响或者复杂的案件。',2,2,'["纪委工作条例", "领导体制"]'::jsonb,'《中国共产党纪律检查委员会工作条例》第六条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (50,7,4,'党的纪律检查工作坚持把一体推进______、不能腐、不想腐作为反腐败斗争的基本方针、新时代全面从严治党的重要方略。','72a14914307de994433abc48e389b10a',NULL,'{"blanks": [["不敢腐"]]}'::jsonb,'《中国共产党纪律检查委员会工作条例》第二十九条规定：坚持一体推进不敢腐、不能腐、不想腐，惩治震慑、制度约束、提高觉悟一体发力。',1,4,'["纪委工作条例", "三不腐"]'::jsonb,'《中国共产党纪律检查委员会工作条例》第二十九条',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (51,7,5,'简述纪检监察机关对问题线索的四类处置方式及其基本含义。','17cbda23a375b0068095faf65b04c0cd',NULL,'{"reference": "按照《中国共产党纪律检查机关监督执纪工作规则》，问题线索按照四类方式处置：①谈话函询：通过谈话或者发函方式由被反映人作出说明，适用于反映一般性、苗头性的问题线索；②初步核实：对涉嫌违纪需要追究党纪责任的问题线索进行初步核查，为是否立案提供依据；③暂存待查：对反映的问题虽然具有一定的可查性，但由于时机、条件等因素暂不具备核查条件的，暂时存放，条件具备时及时启动；④予以了结：对反映失实、没有可查性或者经过核查未发现问题的线索予以了结。", "points": ["谈话函询：由被反映人作出说明", "初步核实：为立案提供依据", "暂存待查：条件不具备时暂存，具备时启动", "予以了结：失实或无可查性的线索了结", "件件有着落"]}'::jsonb,'线索处置是监督执纪工作的源头环节，四类方式须严格按程序审批。',2,10,'["监督执纪工作规则", "线索处置"]'::jsonb,'《中国共产党纪律检查机关监督执纪工作规则》',2,1,now(),1) ON CONFLICT DO NOTHING;
INSERT INTO t_ques_item (id,bank_id,ques_type,stem,stem_md5,options,answer,analysis,difficulty,score_suggest,knowledge_tags,source,status,audit_by,audit_time,create_by) VALUES (52,7,5,'简述派驻机构根据派出机关授权开展监督执纪问责工作的主要职责（列举四项以上）。','14f38e5abcae49c23e3023bae1ff0984',NULL,'{"reference": "根据《中国共产党纪律检查委员会工作条例》第四十四条，派驻机构主要职责包括：加强对驻在单位（含综合监督单位）的监督，重点监督领导班子及其成员；监督促进驻在单位领导班子贯彻落实党的理论和路线方针政策、党中央决策部署，履行全面从严治党主体责任；经常、及时向派出机关报告情况和问题；加强对驻在单位纪检机构的业务指导和监督检查；认真处理信访举报，对问题线索进行集中管理和处置；依规依纪开展纪律审查，严肃查处违纪问题；按照管理权限作出问责决定或者提出问责建议；协助驻在单位党组（党委）做好巡视巡察工作。", "points": ["监督驻在单位领导班子及其成员", "督促落实党中央决策部署和主体责任", "及时向派出机关报告情况和问题", "业务指导驻在单位纪检机构", "处理信访举报、管理处置问题线索", "开展纪律审查、问责决定或建议", "协助巡视巡察工作"]}'::jsonb,'派驻机构是派出它的纪委监委的组成部分，由派出机关直接领导、统一管理。',2,10,'["纪委工作条例", "派驻监督"]'::jsonb,'《中国共产党纪律检查委员会工作条例》第四十四条',2,1,now(),1) ON CONFLICT DO NOTHING;

